def eulerian_num(n, m):
    if n == 0 and m == 0:
        return 1
    elif n == 0:
        return 0
    elif m > n:
        return 0

    # Initialize a 2D list to store the Eulerian numbers
    A = [[0] * (n + 1) for _ in range(n + 1)]

    # Base cases
    A[0][0] = 1
    for i in range(1, n + 1):
        A[i][0] = (i + 1) * A[i - 1][0]
        for j in range(1, i + 1):
            A[i][j] = (j + 1) * A[i - 1][j] + (i - j) * A[i - 1][j - 1]

    return A[n][m]
```

