def is_majority(arr, n, element):
    def binary_search(arr, n, element):
        low, high = 0, n - 1
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] < element:
                low = mid + 1
            elif arr[mid] > element:
                high = mid - 1
            else:
                return mid
        return -1

    index = binary_search(arr, n, element)

    if index == -1:
        return False

    start, end = index, index
    while start > 0 and arr[start - 1] == element:
        start -= 1
    while end < n - 1 and arr[end + 1] == element:
        end += 1

    count = end - start + 1
    return count > n // 2
```

