def max_sub_array_sum_repeated(nums, n, k):
    def kadane(arr):
        max_so_far = arr[0]
        max_ending_here = arr[0]
        for x in arr[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    if k == 1:
        return kadane(nums)

    # Calculate kadane for two concatenated arrays
    double_kadane = kadane(nums * 2)

    # Calculate the sum of the original array
    array_sum = sum(nums)

    # If array_sum is positive and k > 1, the result can extend over multiple arrays
    if array_sum > 0:
        return double_kadane + (k - 2) * array_sum
    else:
        return double_kadane
