def max_sub_array_sum_repeated(arr, n, k):
    def kadane(arr):
        max_ending_here = max_so_far = arr[0]
        for x in arr[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    # Sum of the original array
    array_sum = sum(arr)

    # Maximum subarray sum for one instance of the array using Kadane's Algorithm
    max_kadane = kadane(arr)

    if k == 1:
        return max_kadane

    # Compute the maximum prefix sum
    prefix_sum = 0
    max_prefix_sum = float('-inf')
    for i in range(n):
        prefix_sum += arr[i]
        max_prefix_sum = max(max_prefix_sum, prefix_sum)

    # Compute the maximum suffix sum
    suffix_sum = 0
    max_suffix_sum = float('-inf')
    for i in range(n - 1, -1, -1):
        suffix_sum += arr[i]
        max_suffix_sum = max(max_suffix_sum, suffix_sum)

    # Maximum sum for k-repeated array
    if array_sum > 0:
        return max(max_kadane, max_prefix_sum + max_suffix_sum + (k - 2) * array_sum)
    else:
        return max(max_kadane, max_prefix_sum + max_suffix_sum)
